                    placeholder={demo ? "123456" : undefined}
                  />
                </Field>
              </div>
            )}
            {error !== null && (
              <p
                role="alert"
                className="mt-4 text-xs text-destructive-foreground"
              >
                {authWorkflowErrorMessage(error, locale)}
              </p>
            )}
            <DialogFooter>
              <Button
                type="button"
                variant="outline"
                onClick={() => {
                  request.current?.abort();
                  setReview(null);
                }}
              >
                {l("Cancel", "Cancelar")}
              </Button>
              <Button type="submit" variant="destructive" loading={busy}>
                {l("Confirm", "Confirmar")}
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>
    </section>
  );
}

