          id: "demo-session-laptop",
          device: "Safari · MacBook",
          location: "Local preview",
          createdAt: now(),
          lastActiveAt: now(),
          expiresAt: later(),
          current: false,
        },
        {
          id: "demo-session-phone",
          device: "Chrome · Android",
          location: "Local preview",
          createdAt: now(),
          lastActiveAt: now(),
          expiresAt: later(),
          current: false,
        },
