      {
        organization: {
          id: "demo-studio",
          name: "Aureform Studio",
          slug: "aureform-studio",
          role: "owner",
        },
        members: [
          { id: "demo-member-alex", user: { ...user }, role: "owner" },
          {
            id: "demo-member-sam",
            user: {
              id: "demo-user-sam",
              name: "Sam Rivera",
              email: "sam@example.com",
              emailVerified: true,
            },
            role: "admin",
          },
          {
            id: "demo-member-jordan",
            user: {
              id: "demo-user-jordan",
              name: "Jordan Lee",
              email: "jordan@example.com",
              emailVerified: true,
            },
            role: "member",
